<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Register</title><link href="https://fonts.googleapis.com/css2?family=Libre+Baskerville:wght@400;700&family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="<?php echo e(asset("css/style.css")); ?>"></head><body><div class="auth-box"><h1>Create Account</h1><p class="sub">Join the community hub.</p><?php if($errors->any()): ?><div class="err"><?php echo e($errors->first()); ?></div><?php endif; ?><form method="post" action="<?php echo e(route("register")); ?>"><?php echo csrf_field(); ?><label>Display Name</label><input type="text" name="display_name" required><label>Email</label><input type="email" name="email" required><label>Password (8+)</label><input type="password" name="password" required minlength="8"><button class="btn-primary">Create Account</button></form><p class="link">Have an account? <a href="<?php echo e(route("login")); ?>">Sign In</a></p></div></body></html><?php /**PATH C:\xampp\htdocs\guilford-laravel\resources\views/auth/register.blade.php ENDPATH**/ ?>